from scapy.all import *

packets = rdpcap('/work/workstation.pcap')

# Collect all DNS qnames (queries and responses)
def get_qname(pkt):
    if 'DNS' in pkt.layers():
        dns = pkt['DNS']
        # Get the question section (queries)
        if hasattr(dns, 'qd') and dns.qd:
            try:
                qname = dns.qd[0].qname.decode()
                return qname
            except:
                pass
    return None

qnames = []
for pkt in packets:
    qname = get_qname(pkt)
    if qname and len(qname) > 0:
        qnames.append(qname)

print(f"Unique DNS query names: {len(set(qnames))}")
print("\nAll unique qnames (shortened):")
qnames = sorted(set(qnames))[:50]
for q in qnames:
    print(f"{q}")
