from scapy.all import *
import re

packets = rdpcap('/work/workstation.pcap')

# Collect all DNS queries
def get_dns_qname(pkt):
    if 'DNS' in pkt.layers():
        return pkt['DNS'].qd[0].qname.decode()
    return None

queries = {}
for i, pkt in enumerate(packets):
    qname = get_dns_qname(pkt)
    if qname:
        # Parse base domain and subdomain
        parts = qname.split('.')
        if len(parts) >= 3:
            full_sub = '.'.join(parts[:-2])
            base = '.'.join(parts[-2:])
        else:
            full_sub = qname.rstrip('.')
            base = qname.rstrip('.')

        queries[full_sub] = queries.get(full_sub, 0) + 1

print("Query frequency analysis:")
for sub, cnt in sorted(queries.items(), key=lambda x: -x[1]):
    print(f"{sub}: {cnt} queries")
